import 'package:firebase_core/firebase_core.dart';

import 'options.dart';

/// Firebase settings for this app (com.konduct.rider), generated by FlutterFire into options.dart.
///
/// `--dart-define=KONDUCT_DEMO=true` runs on the demo repository instead (SMS code 123456).
const _forceDemo = bool.fromEnvironment('KONDUCT_DEMO');

FirebaseOptions? firebaseOptions() => _forceDemo ? null : DefaultFirebaseOptions.currentPlatform;
